speaker=pagehero('Speaking & podcasts','Practical conversations.<br>Real operating experience.','Book Nicholas Korom for conversations about entrepreneurship, business exits, and short-term rental acquisitions.')+section(heading('Topics for your audience','From business building to property ownership.')+cards([('The entrepreneur’s next chapter','Lessons from building and exiting a business, then bringing an operating mindset to real estate.',''),('Inside an STR acquisition','The questions, assumptions, and responsibilities that come between finding a listing and buying a property.',''),('Building a coordinated team','How sourcing, transactions, project work, and local operations connect around the investor.','')]))+section('''<div class="split"><div><span class="eyebrow">Booking inquiry</span><h2>Tell me about<br>your audience.</h2></div><div><p>Include the event or podcast name, audience, proposed topic, date, format, location, and your contact information in your inquiry.</p>'''+button('Request a speaking booking','https://www.nickkorom.com/contact/')+'''<p class="small-note" style="margin-top:20px">Booking requests currently use Nicholas’s existing contact form.</p></div></div>''','alt')
