 doc=f'<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{html.escape(title)}</title><meta name="description" content="{html.escape(desc,quote=True)}"><link rel="canonical" href="{url}"><meta property="og:type" content="website"><meta property="og:title" content="{html.escape(title,quote=True)}"><meta property="og:description" content="{html.escape(desc,quote=True)}"><meta property="og:url" content="{url}"><meta property="og:image" content="{base}/assets/nick-speaking.jpg"><meta name="twitter:card" content="summary_large_image"><meta name="theme-color" content="#172724"><link rel="icon" href="/assets/favicon.svg" type="image/svg+xml"><link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin><link rel="stylesheet" href="/assets/site.css"><script type="application/ld+json">{json.dumps(schema)}</script></head><body>{header}<main id="main">{content}</main>{footer}</body></html>'
 out=root/(slug+'/index.html' if slug else 'index.html');out.parent.mkdir(exist_ok=True,parents=True);out.write_text(doc)
